def contains(haystack, needle):
    lo, hi = 0, len(haystack) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if haystack[mid] == needle:
            return True
        if haystack[mid] < needle:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

def pair_sum(values, target):
    lo, hi = 0, len(values) - 1
    while lo < hi:
        total = values[lo] + values[hi]
        if total == target:
            return (lo, hi)
        if total < target:
            lo += 1   # too small: the largest remaining partner still is
        else:
            hi -= 1   # too big: the smallest remaining partner still is
    return None

from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([(start, [start])])
    seen = {start}
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for nxt in graph.get(node, ()):
            if nxt not in seen:      # mark on enqueue, not on dequeue
                seen.add(nxt)
                queue.append((nxt, path + [nxt]))
    return None

